import React, { useState, useEffect, useRef } from 'react';
import './Carrusel.css';

export default function Carrusel() {
  const [slides, setSlides] = useState([]); // Ahora cargamos los datos dinámicamente desde el backend
  const [currentSlide, setCurrentSlide] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const [cargando, setCargando] = useState(true);
  const intervalRef = useRef(null);
  const timeoutRef = useRef(null);

  // REQUERIMIENTO TAREA 4: Consumir las ofertas reales desde la API del backend
  useEffect(() => {
    fetch('http://localhost:8080/api/productos') // Consumimos el catálogo de la API
      .then((res) => res.json())
      .then((data) => {
        // Tomamos los primeros 4 productos que tengan imagen válida para mostrar en el carrusel
        const productosConImagen = data
          .filter(p => p.imagen || p.foto)
          .slice(0, 4)
          .map(p => ({
            image: p.imagen ? `http://localhost:8080/api/imagenes/${p.imagen}` : require("../assets/productos/1DEDO.jpg"),
            name: p.nombre
          }));

        // Si la API devolvió pocos elementos, cargamos un fallback seguro
        if (productosConImagen.length === 0) {
          setSlides([
            { image: require("../assets/productos/1DEDO.jpg"), name: '1DEDO - Limpieza de manos premium' }
          ]);
        } else {
          setSlides(productosConImagen);
        }
        setCargando(false);
      })
      .catch((err) => {
        console.error("Error cargando imágenes del carrusel desde la API:", err);
        // Fallback por defecto si no conecta el backend temporalmente
        setSlides([
          { image: require("../assets/productos/1DEDO.jpg"), name: '1DEDO - Limpieza de manos premium (Modo Offline)' }
        ]);
        setCargando(false);
      });
  }, []);

  const nextSlide = () => {
    if (slides.length <= 1) return;
    resetPauseTimer();
    setCurrentSlide((prevSlide) => (prevSlide + 1) % slides.length);
  };

  const prevSlide = () => {
    if (slides.length <= 1) return;
    resetPauseTimer();
    setCurrentSlide((prevSlide) => (prevSlide - 1 + slides.length) % slides.length);
  };

  const resetPauseTimer = () => {
    setIsPaused(true);
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => {
      setIsPaused(false);
    }, 8000); 
  };

  useEffect(() => {
    if (slides.length <= 1) return;
    if (!isPaused) {
      intervalRef.current = setInterval(() => {
        setCurrentSlide((prevSlide) => (prevSlide + 1) % slides.length);
      }, 4000);
    }

    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, [isPaused, slides]);

  if (cargando) return <div className="carrusel-contenedor" style={{color: '#666', textAlign: 'center', padding: '20px'}}>Cargando banners promocionales...</div>;

  return (
    <div className="carrusel-contenedor" onClick={resetPauseTimer}>
      <div className="carrusel-slides" style={{ transform: `translateX(-${currentSlide * 100}%)` }}>
        {slides.map((slide, index) => (
          <div className="carrusel-slide" key={index}>
            <img src={slide.image} alt={slide.name} className="carrusel-image" />
            <div className="carrusel-overlay">
              <p className="carrusel-name">{slide.name}</p>
            </div>
          </div>
        ))}
      </div>

      {slides.length > 1 && (
        <>
          <button className="carrusel-btn carrusel-prev" onClick={prevSlide}>
            <span>&#10094;</span>
          </button>
          <button className="carrusel-btn carrusel-next" onClick={nextSlide}>
            <span>&#10095;</span>
          </button>
        </>
      )}
    </div>
  );
}
